import Foundation

class DataCacheHelper {
    private var cache: [Int: Int] = [:]

    func computeSquare(_ value: Int) -> Int {
        if let existing = cache[value] {
            return existing
        }
        let result = value * value
        cache[value] = result
        return result
    }
}

let helper = DataCacheHelper()
_ = helper.computeSquare(4)
let cachedResult = helper.computeSquare(4)
print("Square: \(cachedResult)")

