import Foundation

class EvaluationTracker {
    var evaluations = 0

    func evaluateIfChanged(oldVal: Int, newVal: Int) {
        if oldVal != newVal {
            evaluations += 1
        }
    }
}

let tracker = EvaluationTracker()
tracker.evaluateIfChanged(oldVal: 1, newVal: 2)
tracker.evaluateIfChanged(oldVal: 2, newVal: 2)
tracker.evaluateIfChanged(oldVal: 2, newVal: 5)
print("Total evaluations: \(tracker.evaluations)")

import Foundation

struct ItemRecord {
    let stableId: String
    let name: String
}

func countUniqueIdentities(_ items: [ItemRecord]) -> Int {
    Set(items.map { $0.stableId }).count
}

let records = [
    ItemRecord(stableId: "ID_A", name: "First"),
    ItemRecord(stableId: "ID_B", name: "Second"),
    ItemRecord(stableId: "ID_A", name: "First Updated")
]
print("Unique IDs: \(countUniqueIdentities(records))")

import Foundation

struct FeedItem {
    let id: Int
    let isActive: Bool
}

class FilteredFeedModel {
    let allItems: [FeedItem]
    private(set) var activeCount: Int = 0

    init(items: [FeedItem]) {
        self.allItems = items
        self.activeCount = items.filter { $0.isActive }.count
    }
}

let model = FilteredFeedModel(items: [
    FeedItem(id: 1, isActive: true),
    FeedItem(id: 2, isActive: false),
    FeedItem(id: 3, isActive: true)
])
print("Active items: \(model.activeCount)")

import Foundation

struct DiagnosticLogger {
    var changes: [String] = []

    mutating func recordChange(_ propertyName: String) {
        changes.append(propertyName)
    }
}

var logger = DiagnosticLogger()
logger.recordChange("@State count")
logger.recordChange("@Binding text")
print("Logged: \(logger.changes.joined(separator: ", "))")

import Foundation

struct SubviewTracker {
    var evaluatedCount = 0

    mutating func evaluateIfNeeded(hasChanged: Bool) {
        if hasChanged {
            evaluatedCount += 1
        }
    }
}

var tracker = SubviewTracker()
tracker.evaluateIfNeeded(hasChanged: false)
tracker.evaluateIfNeeded(hasChanged: true)
tracker.evaluateIfNeeded(hasChanged: false)
print("Evaluated: \(tracker.evaluatedCount)")

