struct CalculationCache {
    var computedCount: Int = 0

    mutating func computeDouble(_ val: Int) -> Int {
        computedCount += 1
        return val * 2
    }
}

func testCache() {
    var cache = CalculationCache()
    let doubled = cache.computeDouble(5)
    print("Doubled: \(doubled), Count: \(cache.computedCount)")
}

testCache()

